using InsuranceAutomation.Core; using Reqnroll; using InsuranceAutomation.CLEQ.Pages;
namespace InsuranceAutomation.CLEQ.StepDefinitions;
[Binding] public sealed class ApplicationSteps {readonly ScenarioContext _scenario; public ApplicationSteps(ScenarioContext scenario){_scenario=scenario;} [Given("the Commercial Lines ExpertQuote browser session is ready")] public void BrowserReady(){_=_scenario.Get<BrowserSession>().Page;} [Given("test data file {string} is loaded")] public void Load(string file){var path=Path.Combine(AppContext.BaseDirectory,file.Replace('/',Path.DirectorySeparatorChar));var ext=Path.Combine(AppContext.BaseDirectory,"TestData","ExternalDataOverrides.json");_scenario.Get<ScenarioData>().Load(path,ext);} [Given("I open the configured Commercial Lines ExpertQuote application")] public Task Open()=>new ApplicationPage(_scenario.Get<BrowserSession>(),_scenario.Get<ScenarioData>(),_scenario.Get<PageUiActions>()).OpenAsync(); [Given("I sign in to Commercial Lines ExpertQuote using configured credentials")] public Task Login()=>new ApplicationPage(_scenario.Get<BrowserSession>(),_scenario.Get<ScenarioData>(),_scenario.Get<PageUiActions>()).SignInAsync(); }